import{z as s,x as o,o as t,c as i,q as B,j as e,D as E,d as r,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"案例与收束","description":"","frontmatter":{"title":"案例与收束","date":"2026-09-19T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alt-case-map.md","filePath":"quant/alt-case-map.md","lastUpdated":1791063341000}'),d={name:"quant/alt-case-map.md"};function p(u,a,h,D,C,c){const A=o("Mermaid");return t(),i("div",null,[a[2]||(a[2]=B('<h1 id="案例与收束" tabindex="-1">案例与收束 <a class="header-anchor" href="#案例与收束" aria-label="Permalink to &quot;案例与收束&quot;">​</a></h1><div class="epigraph"><p>另类数据的失败很少死于数据本身，多数死于把「有一份新数据」当成了「有一个可交易的问题」；收束时把每一条走过的路标价，学费才会变成资产。</p><footer>—— 据本课程各课的失败清单与五站流水线整理</footer></div><p><a href="/quant/alt-data-to-strategy">上一课</a>把另类数据接到策略上：五站流水线的每站都有门禁，判据在看数据之前签字。本课是<a href="/quant/alt-cost-structure">另类数据工程</a>课程的收束：把七条数据线与一条工程线走过之后剩下的东西——案例、失败模式与可复用的检查次序——收进一张决策单。后课默认已经读完本课程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>另类数据的账很难算平，原因不是任何单点太难，而是失败分散在太多环节：数据可能没错但问题错了，问题可能没错但排他性买贵了，IC 可能不差但换手吃光了边际。缺口是把这门课程的各课收成一次「复盘演练」：给定一条新数据，先问什么、后问什么、在哪里放弃，以及放弃的学费如何记账。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>复盘用三栏对账。第一栏是<strong>数据线</strong>：文本（<a href="/quant/alt-text-deep">文本因子的深化</a>）要付表征升级的增量证据，供应链（<a href="/quant/alt-supply-graph">供应链图谱</a>）要验证冲击真的沿边传播，地理（<a href="/quant/alt-geo-deep">地理空间的深化</a>）要检查地块到公司的映射误差，卡数据（<a href="/quant/alt-card-data">交易卡数据</a>）要对齐授权与结算两个时钟。第二栏是<strong>工程线</strong>：爬虫的许可边界（<a href="/quant/alt-crawler-compliance">网络爬虫的合规与工程</a>）在立项前签字，质量的验收阈值（<a href="/quant/alt-data-quality">数据质量体系</a>）在试用协议里钉死。第三栏是<strong>钱</strong>：排他性、交付与衰减的合同结构（<a href="/quant/alt-cost-structure">成本结构</a>）决定 IC 的门槛，五站流水线（<a href="/quant/alt-data-to-strategy">从数据到策略</a>）决定何时退出。</p>',7)),(t(),e(l,null,{default:E(()=>[n(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%80%E6%9D%A1%E6%96%B0%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20L%5B%22%E6%95%B0%E6%8D%AE%E7%BA%BF%EF%BC%9A%E8%A1%A8%E5%BE%81%2F%E6%98%A0%E5%B0%84%2F%E6%97%B6%E9%92%9F%E6%A3%80%E6%9F%A5%22%5D%0A%20%20Q%20--%3E%20E%5B%22%E5%B7%A5%E7%A8%8B%E7%BA%BF%EF%BC%9A%E8%AE%B8%E5%8F%AF%E4%B8%8E%E9%AA%8C%E6%94%B6%E9%98%88%E5%80%BC%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E9%92%B1%EF%BC%9A%E5%90%88%E5%90%8C%E7%BB%93%E6%9E%84%E4%B8%8E%20IC%20%E9%97%A8%E6%A7%9B%22%5D%0A%20%20L%20--%3E%20G%7B%22%E4%BA%94%E7%AB%99%E9%97%A8%E7%A6%81%E4%BE%9D%E6%AC%A1%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20E%20--%3E%20G%0A%20%20C%20--%3E%20G%0A%20%20G%20--%3E%7C%22%E6%98%AF%22%7C%20S%5B%22%E7%BB%84%E5%90%88%E6%8E%A5%E5%85%A5%E4%B8%8E%E7%94%9F%E4%BA%A7%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20G%20--%3E%7C%22%E5%90%A6%22%7C%20A%5B%22%E6%94%BE%E5%BC%83%E5%B9%B6%E5%BD%92%E6%A1%A3%EF%BC%9A%E5%88%A4%E6%8D%AE%2B%E6%AD%BB%E5%9B%A0%2B%E5%AD%A6%E8%B4%B9%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<p><span class="marginnote">放弃也要归档：判据、死因与已付成本三条都留痕，下一次同类数据进场时，折价的计算才有分母。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三个案例型失败贯穿本课程。其一，<strong>表征升级不付证据</strong>：换大模型重跑文本分数，IC 提升但与新数据源的暴露几乎重合——增量证据的判据（<a href="/quant/alt-text-deep">文本因子的深化</a>）没签就动手，学费是被折价的数据费。其二，<strong>两个时钟混成一个日期</strong>：卡数据用授权日聚合结算额，日历前移造出「提前知道」的假象（<a href="/quant/alt-card-data">交易卡数据</a>），回测漂亮、实盘归零——验收阈值里没有时钟对齐这一条（<a href="/quant/alt-data-quality">数据质量体系</a>）。其三，<strong>排他性买成沉没成本</strong>：独家合同按年付，但数据的可交易寿命只有两个季度（<a href="/quant/alt-cost-structure">成本结构</a>），衰减判据（<a href="/quant/alt-data-to-strategy">从数据到策略</a>）触发时舍不得退。三条路的共同点：错误在第一周就可见，只是没人被要求去看。</p><p><span class="marginnote">IC（信息系数）就是「预测与现实的命中率」：把因子分数和下期收益各排一次序，算两列排名的相关。0.05 的月度 IC 听起来可怜，但配合低换手与足够宽的截面，年化后可能就是一条可用的曲线；同样的 0.05 若出现在高换手信号上，一半被成本吃掉，就什么也不剩。</span></p><p>三种死法与它们在第一周的暴露信号——回答「每条路最早在哪里亮红灯」：</p>',5)),(t(),e(l,null,{default:E(()=>[n(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E6%AD%BB%E6%B3%95%E4%B8%80%EF%BC%9A%E8%A1%A8%E5%BE%81%E5%8D%87%E7%BA%A7%E4%B8%8D%E4%BB%98%E5%A2%9E%E9%87%8F%E8%AF%81%E6%8D%AE%22%5D%20--%3E%20W1%5B%22%E7%BA%A2%E7%81%AF%EF%BC%9A%E6%96%B0%E5%88%86%E6%95%B0%E4%B8%8E%E6%97%A7%E6%95%B0%E6%8D%AE%E6%BA%90%E6%9A%B4%E9%9C%B2%E7%9B%B8%E5%85%B3%E6%80%A7%E8%BF%87%E9%AB%98%22%5D%0A%20%20F2%5B%22%E6%AD%BB%E6%B3%95%E4%BA%8C%EF%BC%9A%E6%8E%88%E6%9D%83%E6%97%A5%E4%B8%8E%E7%BB%93%E7%AE%97%E6%97%A5%E6%B7%B7%E8%AE%B0%22%5D%20--%3E%20W2%5B%22%E7%BA%A2%E7%81%AF%EF%BC%9A%E5%9B%9E%E6%B5%8B%E9%A2%86%E5%85%88%E6%80%A7%E5%AE%8C%E7%BE%8E%EF%BC%8C%E5%AE%9E%E7%9B%98%E9%80%90%E6%B8%90%E5%BD%92%E9%9B%B6%22%5D%0A%20%20F3%5B%22%E6%AD%BB%E6%B3%95%E4%B8%89%EF%BC%9A%E6%8E%92%E4%BB%96%E5%90%88%E5%90%8C%E9%95%BF%E4%BA%8E%E6%95%B0%E6%8D%AE%E5%AF%BF%E5%91%BD%22%5D%20--%3E%20W3%5B%22%E7%BA%A2%E7%81%AF%EF%BC%9A%E8%A1%B0%E5%87%8F%E5%88%A4%E6%8D%AE%E5%B7%B2%E8%A7%A6%E5%8F%91%E5%8D%B4%E6%97%A0%E4%BA%BA%E6%89%A7%E8%A1%8C%E9%80%80%E5%87%BA%22%5D%0A%20%20W1%20--%3E%20X%5B%22%E4%BB%BB%E4%B8%80%E7%BA%A2%E7%81%AF%E5%8D%B3%E6%AD%A2%E6%8D%9F%E5%BD%92%E6%A1%A3%EF%BC%8C%E4%B8%8D%E8%BF%9B%E4%B8%8B%E4%B8%80%E7%AB%99%22%5D%0A%20%20W2%20--%3E%20X%0A%20%20W3%20--%3E%20X%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<p><span class="marginnote">排他费是典型的沉没成本：钱已经付了，理性问题是「从今天起继续用它还值不值」，而不是「不用就白买了」。工程上的解法是把退出判据写进合同与流水线本身，触发即执行，让「舍不得」没有操作空间。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程的口径止于数据侧的工程与研究纪律：信号进了组合之后的风险叠加、容量与执行在组合与执行课程里；「数据比市场聪明」的极端情形——信息本身来自违规——不在任何流水线的允许集里。另类数据的监管口径也在移动：-web-data-compliance 一课的合规清单要按当期规则重读，本课程不给跨期承诺。</p><p><span class="marginnote">初学者容易被「内幕级数据」的故事吸引。实际上来源违规的数据不是 alpha 加成，而是法律与声誉的负资产：收益无法入账、回测无法披露、供应商随时被查封。合规清单要当成这类策略的准入证来读，而不是事后补的成本项。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复盘三栏对账：数据线逐域检查表征、映射与时钟，工程线把许可与阈值前置，钱线把合同结构折进 IC 门槛。</li><li>三条高频死法：表征升级不付增量证据、多时钟混一日期、排他性合同长于数据寿命——都在第一周可见。</li><li>放弃是产出：判据、死因、学费三件归档，同类数据的折价才有分母。</li><li>检查次序固定为「先许可、再质量阈值、后花钱」，顺序错了后面全对不了。</li><li>出处：本课程各课的失败清单；多重检验折价口径见 Bailey, Borwein, López de Prado and Zhu, 2014。</li></ul>',6))])}const f=s(d,[["render",p]]);export{_ as __pageData,f as default};
